:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --border-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.score-board {
  font-size: 1.25rem;
  font-weight: 600;
}

#score {
  color: var(--accent);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 400px;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: #0d1b2a;
  border-radius: 8px;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(13, 27, 42, 0.85);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 16px;
  border-radius: 8px;
  padding: 16px;
  text-align: center;
}

.overlay.hidden {
  display: none;
}

.overlay p {
  font-size: 1.1rem;
  line-height: 1.5;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  background: var(--primary);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 10px 24px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: #1a4a7a;
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
  background: #0a2a4a;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.instructions {
  font-size: 0.95rem;
  opacity: 0.8;
  text-align: center;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .btn {
    padding: 8px 16px;
    min-width: 80px;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const overlay = document.getElementById('overlay');
const overlayMessage = document.getElementById('overlayMessage');
const overlayButton = document.getElementById('overlayButton');
const pauseBtn = document.getElementById('pauseBtn');
const restartBtn = document.getElementById('restartBtn');

const GRID_SIZE = 20;
const TILE_COUNT = canvas.width / GRID_SIZE;

let snake = [];
let food = { x: 0, y: 0 };
let direction = { x: 0, y: 0 };
let nextDirection = { x: 0, y: 0 };
let score = 0;
let gameState = 'paused'; // 'paused', 'running', 'gameover'
let gameLoop = null;
let speed = 150;

function initGame() {
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  nextDirection = { x: 0, y: 0 };
  score = 0;
  scoreEl.textContent = '0';
  placeFood();
  draw();
}

function placeFood() {
  let newFood;
  do {
    newFood = {
      x: Math.floor(Math.random() * TILE_COUNT),
      y: Math.floor(Math.random() * TILE_COUNT)
    };
  } while (snake.some(seg => seg.x === newFood.x && seg.y === newFood.y));
  food = newFood;
}

function draw() {
  ctx.fillStyle = '#0d1b2a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw food
  ctx.fillStyle = '#e94560';
  ctx.fillRect(food.x * GRID_SIZE, food.y * GRID_SIZE, GRID_SIZE - 1, GRID_SIZE - 1);

  // Draw snake
  snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#eaeaea' : '#4a9eff';
    ctx.fillRect(seg.x * GRID_SIZE, seg.y * GRID_SIZE, GRID_SIZE - 1, GRID_SIZE - 1);
  });
}

function update() {
  if (gameState !== 'running') return;

  direction = { ...nextDirection };
  if (direction.x === 0 && direction.y === 0) return;

  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  // Wall collision
  if (head.x < 0 || head.x >= TILE_COUNT || head.y < 0 || head.y >= TILE_COUNT) {
    endGame();
    return;
  }

  // Self collision
  if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
    endGame();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = score;
    placeFood();
  } else {
    snake.pop();
  }

  draw();
}

function startLoop() {
  if (gameLoop) clearInterval(gameLoop);
  gameLoop = setInterval(update, speed);
}

function stopLoop() {
  if (gameLoop) {
    clearInterval(gameLoop);
    gameLoop = null;
  }
}

function startGame() {
  if (gameState === 'running') return;
  if (gameState === 'gameover') {
    initGame();
  }
  gameState = 'running';
  overlay.classList.add('hidden');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
  startLoop();
}

function pauseGame() {
  if (gameState !== 'running') return;
  gameState = 'paused';
  stopLoop();
  overlayMessage.textContent = 'Game Paused';
  overlayButton.textContent = 'Resume';
  overlay.classList.remove('hidden');
  pauseBtn.textContent = 'Resume';
  pauseBtn.setAttribute('aria-label', 'Resume game');
}

function resumeGame() {
  if (gameState !== 'paused') return;
  gameState = 'running';
  overlay.classList.add('hidden');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
  startLoop();
}

function endGame() {
  gameState = 'gameover';
  stopLoop();
  overlayMessage.textContent = `Game Over! Score: ${score}`;
  overlayButton.textContent = 'Restart';
  overlay.classList.remove('hidden');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
}

function restartGame() {
  stopLoop();
  gameState = 'paused';
  initGame();
  overlayMessage.textContent = 'Press Start or use arrow keys to play';
  overlayButton.textContent = 'Start';
  overlay.classList.remove('hidden');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
}

function handleKey(e) {
  const key = e.key;
  if (key === 'p' || key === 'P') {
    e.preventDefault();
    if (gameState === 'running') pauseGame();
    else if (gameState === 'paused') resumeGame();
    return;
  }

  if (gameState !== 'running') {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (gameState === 'paused') resumeGame();
    }
    return;
  }

  const dirs = {
    ArrowUp: { x: 0, y: -1 },
    ArrowDown: { x: 0, y: 1 },
    ArrowLeft: { x: -1, y: 0 },
    ArrowRight: { x: 1, y: 0 }
  };

  if (dirs[key]) {
    e.preventDefault();
    const newDir = dirs[key];
    if (newDir.x !== -direction.x || newDir.y !== -direction.y) {
      nextDirection = newDir;
    }
  }
}

// Event listeners
overlayButton.addEventListener('click', () => {
  if (gameState === 'gameover') restartGame();
  else if (gameState === 'paused') resumeGame();
  else startGame();
});

pauseBtn.addEventListener('click', () => {
  if (gameState === 'running') pauseGame();
  else if (gameState === 'paused') resumeGame();
});

restartBtn.addEventListener('click', restartGame);

document.addEventListener('keydown', handleKey);

// Initialize
initGame();
overlayMessage.textContent = 'Press Start or use arrow keys to play';
overlayButton.textContent = 'Start';
